from json_text import *
def string_map_from_config(data: str) -> dict[str, str]:
    values: dict[str, str] = {}
    lines: list[str] = data.splitlines()
    for line in lines:
        trimmed: str = line.strip()
        if trimmed == '' or trimmed.startswith('#'):
            continue
        separator: int = line.find('=')
        if separator < 0:
            raise ValueError
        key: str = line[:separator].strip()
        if key == '':
            raise ValueError
        values[key] = line[separator + 1:]
    return values

def string_map_copy(values: dict[str, str]) -> dict[str, str]:
    return values.copy()

def string_map_merge(left: dict[str, str], right: dict[str, str]) -> dict[str, str]:
    result: dict[str, str] = left.copy()
    result.update(right)
    return result

def string_map_keys(values: dict[str, str]) -> list[str]:
    return values.keys()

def string_map_values(values: dict[str, str]) -> list[str]:
    return values.values()

def string_map_render(values: dict[str, str]) -> str:
    parts: list[str] = []
    for key, value in values.items():
        parts.append(json_quote(key) + ':' + json_quote(value))
    return '{' + ','.join(parts) + '}\n'
